INSERT INTO `products` VALUES (1,'srm-nha-dam','SRM-ND-150','Sữa Rửa Mặt Nha Đam','Sữa rửa mặt',219000.00,NULL,'<div style=\"margin-bottom: 24px;\"><strong style=\"display: block; color: #264F40; font-size: 18px; margin-bottom: 20px;\">Dịu lành từ thiên nhiên, nâng niu làn da mỗi ngày</strong><p style=\"margin: 0 0 16px 0; color: #56635D; line-height: 1.8;\">Bắt đầu hành trình chăm sóc da từ bước làm sạch nhẹ nhàng cùng Mộc Yên. Lấy cảm hứng từ <b>nha đam</b> và sức sống của thiên nhiên, sản phẩm giúp loại bỏ bụi bẩn, bã nhờn tích tụ mà vẫn hướng đến cảm giác mềm mại, dễ chịu cho làn da.</p><p style=\"margin: 0 0 16px 0; color: #56635D; line-height: 1.8;\">Với định hướng chăm sóc da tối giản, sữa rửa mặt nha đam Mộc Yên là lựa chọn dành cho những ai tìm kiếm sự cân bằng giữa <b>làm sạch và dưỡng ẩm</b> trong quy trình chăm sóc da hằng ngày.</p><div style=\"margin-top: 24px; padding: 16px 20px; background: #F8F9F5; border-left: 3px solid #658354; border-radius: 6px;\"><p style=\"margin: 0; color: #56635D; line-height: 1.8; font-style: italic; font-size: 14px;\"><b>Thông điệp:</b> Làm sạch vừa đủ. Dịu nhẹ mỗi ngày.</p></div></div>','Sữa rửa mặt nha đam Mộc Yên nhẹ nhàng làm sạch bụi bẩn và bã nhờn, đồng thời giúp làn da duy trì độ ẩm tự nhiên. Công thức dịu nhẹ mang đến cảm giác mềm mại, dễ chịu sau mỗi lần sử dụng.','<div style=\"margin-bottom: 24px;\"><ul style=\"list-style: none; padding: 0; margin: 0;\"><li style=\"display: flex; gap: 12px; margin-bottom: 18px; color: #56635D; line-height: 1.8;\"><span style=\"color: #658354; font-size: 18px;\">✦</span><div><strong style=\"color: #264F40;\">Làm sạch nhẹ nhàng:</strong> Loại bỏ bụi bẩn, bã nhờn và tạp chất trên bề mặt da.</div></li><li style=\"display: flex; gap: 12px; margin-bottom: 18px; color: #56635D; line-height: 1.8;\"><span style=\"color: #658354; font-size: 18px;\">✦</span><div><strong style=\"color: #264F40;\">Làm dịu làn da:</strong> Mang lại cảm giác dễ chịu, giúp da trông tươi tắn sau khi rửa.</div></li><li style=\"display: flex; gap: 12px; margin-bottom: 18px; color: #56635D; line-height: 1.8;\"><span style=\"color: #658354; font-size: 18px;\">✦</span><div><strong style=\"color: #264F40;\">Duy trì độ ẩm:</strong> Hỗ trợ hạn chế cảm giác khô căng sau bước làm sạch.</div></li><li style=\"display: flex; gap: 12px; margin-bottom: 18px; color: #56635D; line-height: 1.8;\"><span style=\"color: #658354; font-size: 18px;\">✦</span><div><strong style=\"color: #264F40;\">Hỗ trợ hàng rào bảo vệ da:</strong> Hướng đến làn da mềm mại, cân bằng và khỏe khoắn.</div></li></ul></div>','<div style=\"margin-bottom: 24px;\"><strong style=\"display: block; color: #264F40; font-size: 16px; margin-bottom: 8px;\">Nha đam (Aloe Vera)</strong><p style=\"margin: 0; color: #56635D; line-height: 1.8;\">Giúp cấp ẩm, làm dịu và mang lại cảm giác tươi mát cho làn da. Là thành phần chủ đạo tạo nên cảm hứng thiên nhiên và tinh thần dịu nhẹ của sản phẩm.</p></div><div style=\"margin-bottom: 24px;\"><strong style=\"display: block; color: #264F40; font-size: 16px; margin-bottom: 8px;\">Glycerin</strong><p style=\"margin: 0; color: #56635D; line-height: 1.8;\">Thành phần hút ẩm giúp duy trì độ ẩm trên bề mặt da, hỗ trợ hạn chế cảm giác khô căng sau khi làm sạch.</p></div><div style=\"margin-bottom: 24px;\"><strong style=\"display: block; color: #264F40; font-size: 16px; margin-bottom: 8px;\">Chiết xuất trà xanh (Green Tea Extract)</strong><p style=\"margin: 0; color: #56635D; line-height: 1.8;\">Bổ sung cảm hứng chăm sóc da từ thực vật, hỗ trợ bảo vệ da trước các tác động từ môi trường.</p></div><div style=\"padding: 20px; background: #F8F9F5; border-left: 3px solid #658354; border-radius: 6px; margin-top: 30px;\"><strong style=\"display: block; color: #243A30; margin-bottom: 8px;\">Bảng thành phần đầy đủ (INCI)</strong><span style=\"color: #56635D; font-size: 13px; line-height: 1.8; font-style: italic;\">Aqua, Aloe Barbadensis Leaf Juice, Glycerin, Cocamidopropyl Betaine, Decyl Glucoside, Camellia Sinensis Leaf Extract, Panthenol, Citric Acid, Sodium Benzoate, Potassium Sorbate.</span></div>','<div style=\"margin-bottom: 24px;\"><div style=\"display: flex; gap: 15px; margin-bottom: 20px;\"><div style=\"flex-shrink: 0; width: 28px; height: 28px; background: #264F40; color: white; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 600; font-size: 14px;\">1</div><div><strong style=\"display: block; color: #264F40; font-size: 15px; margin-bottom: 4px;\">Làm ướt da</strong><p style=\"margin: 0; color: #56635D; line-height: 1.8; font-size: 14px;\">Làm ướt mặt bằng nước sạch.</p></div></div><div style=\"display: flex; gap: 15px; margin-bottom: 20px;\"><div style=\"flex-shrink: 0; width: 28px; height: 28px; background: #264F40; color: white; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 600; font-size: 14px;\">2</div><div><strong style=\"display: block; color: #264F40; font-size: 15px; margin-bottom: 4px;\">Massage nhẹ nhàng</strong><p style=\"margin: 0; color: #56635D; line-height: 1.8; font-size: 14px;\">Lấy một lượng sữa rửa mặt vừa đủ, tạo bọt và massage nhẹ nhàng trên mặt trong khoảng 30–60 giây.</p></div></div><div style=\"display: flex; gap: 15px; margin-bottom: 30px;\"><div style=\"flex-shrink: 0; width: 28px; height: 28px; background: #264F40; color: white; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 600; font-size: 14px;\">3</div><div><strong style=\"display: block; color: #264F40; font-size: 15px; margin-bottom: 4px;\">Rửa sạch</strong><p style=\"margin: 0; color: #56635D; line-height: 1.8; font-size: 14px;\">Rửa lại với nước, dùng khăn mềm thấm khô và tiếp tục các bước dưỡng da.</p></div></div><div style=\"padding: 20px; background: #F8F9F5; border-left: 3px solid #658354; border-radius: 6px;\"><p style=\"margin: 0 0 10px 0; color: #243A30; font-size: 14px;\"><strong>Tần suất:</strong> <span style=\"color: #56635D;\">Sử dụng sáng và tối hằng ngày.</span></p><p style=\"margin: 0; color: #243A30; font-size: 14px;\"><strong>Lưu ý:</strong> <span style=\"color: #56635D;\">Tránh tiếp xúc trực tiếp với mắt. Ngừng sử dụng nếu xuất hiện dấu hiệu kích ứng.</span></p></div></div>','Da nhạy cảm','150ml','aloe-cleanser.png','[\"aloe-cleanser.png\", \"aloe-cleanser-1.png\"]',100,'active',0),(2,'srm-lien-hoa','SRM-LH-150','Sữa Rửa Mặt Liên Hoa','Sữa rửa mặt',229000.00,NULL,'<div style=\"margin-bottom: 24px;\"><strong style=\"display: block; color: #264F40; font-size: 18px; margin-bottom: 20px;\">Làm sạch dịu dàng, nâng niu làn da khô</strong><p style=\"margin: 0 0 16px 0; color: #56635D; line-height: 1.8;\">Làm sạch là bước khởi đầu quan trọng trong chu trình chăm sóc da. Tuy nhiên, với làn da khô và thiếu ẩm, việc lựa chọn sản phẩm làm sạch phù hợp giúp hạn chế cảm giác căng rít và duy trì sự mềm mại sau khi rửa mặt.</p><p style=\"margin: 0 0 16px 0; color: #56635D; line-height: 1.8;\">Sữa rửa mặt Liên Hoa Mộc Yên lấy cảm hứng từ <b>vẻ đẹp thanh khiết của hoa sen</b>, hướng đến trải nghiệm làm sạch nhẹ nhàng kết hợp chăm sóc độ ẩm cho da. Sản phẩm giúp loại bỏ bụi bẩn và dầu thừa tích tụ trong ngày, đồng thời hỗ trợ duy trì cảm giác ẩm mượt sau khi sử dụng.</p><p style=\"margin: 0 0 16px 0; color: #56635D; line-height: 1.8;\">Với kết cấu dạng kem mềm mịn, sản phẩm dễ dàng tạo bọt khi kết hợp với nước, mang lại cảm giác thư giãn trong quá trình làm sạch. Sắc hồng sen dịu nhẹ cùng tinh thần tối giản của Mộc Yên tạo nên một sản phẩm chăm sóc da gần gũi, phù hợp với thói quen làm đẹp hằng ngày.</p><div style=\"margin-top: 24px; padding: 16px 20px; background: #F8F9F5; border-left: 3px solid #658354; border-radius: 6px;\"><p style=\"margin: 0; color: #56635D; line-height: 1.8; font-style: italic; font-size: 14px;\"><b>Thông điệp:</b> Dịu dàng làm sạch, mềm mại nâng niu.</p></div></div>','Sữa rửa mặt Liên Hoa Mộc Yên giúp loại bỏ bụi bẩn, bã nhờn và tạp chất trên bề mặt da mà vẫn chú trọng duy trì độ ẩm tự nhiên. Lấy cảm hứng từ hoa sen – biểu tượng của vẻ đẹp thanh khiết và dịu dàng, sản phẩm kết hợp các thành phần làm sạch cùng dưỡng chất giữ ẩm, mang đến cảm giác mềm mại, dễ chịu.','<div style=\"margin-bottom: 24px;\"><ul style=\"list-style: none; padding: 0; margin: 0;\"><li style=\"display: flex; gap: 12px; margin-bottom: 18px; color: #56635D; line-height: 1.8;\"><span style=\"color: #658354; font-size: 18px;\">✦</span><div><strong style=\"color: #264F40;\">Làm sạch bụi bẩn:</strong> Giúp loại bỏ bụi bẩn, tạp chất và dầu thừa trên bề mặt da.</div></li><li style=\"display: flex; gap: 12px; margin-bottom: 18px; color: #56635D; line-height: 1.8;\"><span style=\"color: #658354; font-size: 18px;\">✦</span><div><strong style=\"color: #264F40;\">Làm sạch dịu nhẹ:</strong> Hướng đến trải nghiệm làm sạch không gây cảm giác khô căng quá mức sau khi rửa mặt.</div></li><li style=\"display: flex; gap: 12px; margin-bottom: 18px; color: #56635D; line-height: 1.8;\"><span style=\"color: #658354; font-size: 18px;\">✦</span><div><strong style=\"color: #264F40;\">Duy trì độ ẩm tự nhiên:</strong> Hỗ trợ giữ lại cảm giác mềm mại, hạn chế tình trạng da khô ráp sau khi làm sạch.</div></li><li style=\"display: flex; gap: 12px; margin-bottom: 18px; color: #56635D; line-height: 1.8;\"><span style=\"color: #658354; font-size: 18px;\">✦</span><div><strong style=\"color: #264F40;\">Làm mềm bề mặt da:</strong> Giúp làn da có cảm giác mịn màng và dễ chịu hơn.</div></li><li style=\"display: flex; gap: 12px; margin-bottom: 18px; color: #56635D; line-height: 1.8;\"><span style=\"color: #658354; font-size: 18px;\">✦</span><div><strong style=\"color: #264F40;\">Chuẩn bị cho các bước dưỡng da:</strong> Giúp da sạch thoáng, sẵn sàng tiếp nhận toner, tinh chất và kem dưỡng.</div></li></ul></div>','<div style=\"margin-bottom: 24px;\"><strong style=\"display: block; color: #264F40; font-size: 16px; margin-bottom: 8px;\">Chiết xuất hoa sen (Nelumbo Nucifera Flower Extract)</strong><p style=\"margin: 0; color: #56635D; line-height: 1.8;\">Thành phần có nguồn gốc thực vật, chứa các hợp chất chống oxy hóa, góp phần chăm sóc và duy trì vẻ tươi tắn của làn da. Chiết xuất hoa sen tạo nên cảm hứng chủ đạo cho dòng sản phẩm Liên Hoa của Mộc Yên.</p></div><div style=\"margin-bottom: 24px;\"><strong style=\"display: block; color: #264F40; font-size: 16px; margin-bottom: 8px;\">Glycerin</strong><p style=\"margin: 0; color: #56635D; line-height: 1.8;\">Thành phần hút ẩm giúp thu hút và giữ nước trên bề mặt da, hỗ trợ duy trì độ ẩm và hạn chế cảm giác khô căng sau khi làm sạch.</p></div><div style=\"margin-bottom: 24px;\"><strong style=\"display: block; color: #264F40; font-size: 16px; margin-bottom: 8px;\">Cocamidopropyl Betaine</strong><p style=\"margin: 0; color: #56635D; line-height: 1.8;\">Thành phần làm sạch có khả năng tạo bọt, giúp loại bỏ bụi bẩn và dầu thừa với trải nghiệm làm sạch tương đối dịu nhẹ khi được sử dụng trong công thức phù hợp.</p></div><div style=\"margin-bottom: 24px;\"><strong style=\"display: block; color: #264F40; font-size: 16px; margin-bottom: 8px;\">Panthenol (Vitamin B5)</strong><p style=\"margin: 0; color: #56635D; line-height: 1.8;\">Hỗ trợ dưỡng ẩm và làm dịu da, góp phần duy trì cảm giác mềm mại sau khi rửa mặt.</p></div><div style=\"padding: 20px; background: #F8F9F5; border-left: 3px solid #658354; border-radius: 6px; margin-top: 30px;\"><strong style=\"display: block; color: #243A30; margin-bottom: 8px;\">Bảng thành phần đầy đủ (INCI)</strong><span style=\"color: #56635D; font-size: 13px; line-height: 1.8; font-style: italic;\">Aqua, Glycerin, Cocamidopropyl Betaine, Sodium Cocoyl Glutamate, Coco-Glucoside, Nelumbo Nucifera Flower Extract, Panthenol, Allantoin, Citric Acid, Sodium Chloride, Phenoxyethanol, Ethylhexylglycerin.</span></div>','<div style=\"margin-bottom: 24px;\"><div style=\"display: flex; gap: 15px; margin-bottom: 20px;\"><div style=\"flex-shrink: 0; width: 28px; height: 28px; background: #264F40; color: white; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 600; font-size: 14px;\">1</div><div><strong style=\"display: block; color: #264F40; font-size: 15px; margin-bottom: 4px;\">Làm ướt da</strong><p style=\"margin: 0; color: #56635D; line-height: 1.8; font-size: 14px;\">Làm ướt mặt bằng nước sạch, ưu tiên nước có nhiệt độ vừa phải để tránh làm da mất độ ẩm.</p></div></div><div style=\"display: flex; gap: 15px; margin-bottom: 20px;\"><div style=\"flex-shrink: 0; width: 28px; height: 28px; background: #264F40; color: white; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 600; font-size: 14px;\">2</div><div><strong style=\"display: block; color: #264F40; font-size: 15px; margin-bottom: 4px;\">Lấy sản phẩm</strong><p style=\"margin: 0; color: #56635D; line-height: 1.8; font-size: 14px;\">Lấy một lượng sữa rửa mặt vừa đủ ra lòng bàn tay, thêm một ít nước và tạo bọt nhẹ.</p></div></div><div style=\"display: flex; gap: 15px; margin-bottom: 20px;\"><div style=\"flex-shrink: 0; width: 28px; height: 28px; background: #264F40; color: white; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 600; font-size: 14px;\">3</div><div><strong style=\"display: block; color: #264F40; font-size: 15px; margin-bottom: 4px;\">Massage nhẹ nhàng</strong><p style=\"margin: 0; color: #56635D; line-height: 1.8; font-size: 14px;\">Thoa bọt lên mặt, massage theo chuyển động tròn trong khoảng 30–60 giây. Tránh chà xát mạnh và vùng mắt.</p></div></div><div style=\"display: flex; gap: 15px; margin-bottom: 30px;\"><div style=\"flex-shrink: 0; width: 28px; height: 28px; background: #264F40; color: white; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 600; font-size: 14px;\">4</div><div><strong style=\"display: block; color: #264F40; font-size: 15px; margin-bottom: 4px;\">Rửa sạch và dưỡng da</strong><p style=\"margin: 0; color: #56635D; line-height: 1.8; font-size: 14px;\">Rửa kỹ với nước, thấm khô bằng khăn mềm rồi tiếp tục với toner, tinh chất và kem dưỡng ẩm.</p></div></div><div style=\"padding: 20px; background: #F8F9F5; border-left: 3px solid #658354; border-radius: 6px;\"><p style=\"margin: 0 0 10px 0; color: #243A30; font-size: 14px;\"><strong>Tần suất:</strong> <span style=\"color: #56635D;\">Sử dụng sáng và tối hằng ngày hoặc điều chỉnh theo nhu cầu của làn da.</span></p><p style=\"margin: 0; color: #243A30; font-size: 14px;\"><strong>Lưu ý:</strong> <span style=\"color: #56635D;\">Tránh để sản phẩm tiếp xúc trực tiếp với mắt. Ngừng sử dụng nếu xuất hiện dấu hiệu kích ứng. Với da khô, nên ưu tiên sản phẩm làm sạch dịu nhẹ và sử dụng kem dưỡng ẩm sau khi rửa mặt.</span></p></div></div>','Da khô','150ml','lotus-cleanser.png','[\"lotus-cleanser.png\", \"lotus-cleanser-1.png\"]',100,'active',0),(3,'srm-nghe-vang','SRM-NV-150','Sữa Rửa Mặt Nghệ Vàng','Sữa rửa mặt',239000.00,NULL,'<div style=\"margin-bottom: 24px;\"><strong style=\"display: block; color: #264F40; font-size: 18px; margin-bottom: 20px;\">Sạch thoáng từ nghệ vàng, đánh thức vẻ rạng rỡ tự nhiên</strong><p style=\"margin: 0 0 16px 0; color: #56635D; line-height: 1.8;\">Làn da dầu và da hỗn hợp thường dễ tích tụ bã nhờn, bụi bẩn, khiến bề mặt da trở nên bóng nhờn và kém tươi tắn. Một bước làm sạch phù hợp giúp loại bỏ tạp chất hằng ngày, đồng thời tạo nền tảng cho chu trình chăm sóc da tiếp theo.</p><p style=\"margin: 0 0 16px 0; color: #56635D; line-height: 1.8;\">Sữa rửa mặt Nghệ Vàng Mộc Yên lấy cảm hứng từ <b>nghệ vàng</b> – nguyên liệu thực vật gắn liền với những phương pháp chăm sóc da truyền thống tại Việt Nam. Sản phẩm hướng đến khả năng làm sạch bụi bẩn và dầu thừa, giúp da cảm thấy thông thoáng mà vẫn duy trì sự mềm mại sau khi rửa mặt.</p><p style=\"margin: 0 0 16px 0; color: #56635D; line-height: 1.8;\">Kết hợp cùng các thành phần dưỡng ẩm và làm sạch dịu nhẹ, sản phẩm phù hợp với chu trình chăm sóc da hằng ngày. Thiết kế tông vàng ấm cùng sắc xanh olive đặc trưng thể hiện tinh thần mộc mạc, gần gũi thiên nhiên của Mộc Yên.</p><div style=\"margin-top: 24px; padding: 16px 20px; background: #F8F9F5; border-left: 3px solid #658354; border-radius: 6px;\"><p style=\"margin: 0; color: #56635D; line-height: 1.8; font-style: italic; font-size: 14px;\"><b>Thông điệp:</b> Làm sạch từ thiên nhiên, khơi sáng vẻ đẹp nguyên bản.</p></div></div>','Sữa rửa mặt Nghệ Vàng Mộc Yên với chiết xuất nghệ và Salicylic Acid giúp làm sạch sâu, loại bỏ bã nhờn và hỗ trợ kiểm soát dầu hiệu quả. Sản phẩm mang lại làn da sạch thoáng, mềm mại và hỗ trợ làm mờ thâm, phù hợp cho da dầu và da hỗn hợp.','<div style=\"margin-bottom: 24px;\"><ul style=\"list-style: none; padding: 0; margin: 0;\"><li style=\"display: flex; gap: 12px; margin-bottom: 18px; color: #56635D; line-height: 1.8;\"><span style=\"color: #658354; font-size: 18px;\">✦</span><div><strong style=\"color: #264F40;\">Làm sạch bụi bẩn:</strong> Loại bỏ bụi bẩn, tạp chất và dầu thừa tích tụ trên bề mặt da.</div></li><li style=\"display: flex; gap: 12px; margin-bottom: 18px; color: #56635D; line-height: 1.8;\"><span style=\"color: #658354; font-size: 18px;\">✦</span><div><strong style=\"color: #264F40;\">Hỗ trợ kiểm soát dầu:</strong> Giúp giảm cảm giác nhờn rít, mang lại bề mặt da sạch thoáng sau khi rửa mặt.</div></li><li style=\"display: flex; gap: 12px; margin-bottom: 18px; color: #56635D; line-height: 1.8;\"><span style=\"color: #658354; font-size: 18px;\">✦</span><div><strong style=\"color: #264F40;\">Hỗ trợ chăm sóc da có vết thâm:</strong> Chiết xuất nghệ là thành phần cảm hứng cho công thức hướng đến làn da trông tươi tắn và đều màu hơn.</div></li><li style=\"display: flex; gap: 12px; margin-bottom: 18px; color: #56635D; line-height: 1.8;\"><span style=\"color: #658354; font-size: 18px;\">✦</span><div><strong style=\"color: #264F40;\">Duy trì độ ẩm:</strong> Hỗ trợ hạn chế cảm giác khô căng sau bước làm sạch.</div></li><li style=\"display: flex; gap: 12px; margin-bottom: 18px; color: #56635D; line-height: 1.8;\"><span style=\"color: #658354; font-size: 18px;\">✦</span><div><strong style=\"color: #264F40;\">Chuẩn bị cho các bước dưỡng da:</strong> Giúp da sạch thoáng, sẵn sàng tiếp nhận toner, tinh chất và kem dưỡng.</div></li></ul></div>','<div style=\"margin-bottom: 24px;\"><strong style=\"display: block; color: #264F40; font-size: 16px; margin-bottom: 8px;\">Chiết xuất nghệ (Curcuma Longa Root Extract)</strong><p style=\"margin: 0; color: #56635D; line-height: 1.8;\">Thành phần có nguồn gốc thực vật, chứa curcuminoid và các hợp chất chống oxy hóa. Nghệ được sử dụng trong mỹ phẩm nhằm hỗ trợ chăm sóc da, góp phần duy trì vẻ tươi tắn và cải thiện vẻ ngoài của làn da không đều màu.</p></div><div style=\"margin-bottom: 24px;\"><strong style=\"display: block; color: #264F40; font-size: 16px; margin-bottom: 8px;\">Salicylic Acid (BHA)</strong><p style=\"margin: 0; color: #56635D; line-height: 1.8;\">Thành phần hỗ trợ làm sạch sâu trong lỗ chân lông, giúp loại bỏ tế bào chết và bã nhờn tích tụ. Phù hợp với định hướng chăm sóc da dầu, da hỗn hợp và da dễ bít tắc khi được sử dụng ở nồng độ phù hợp.</p></div><div style=\"margin-bottom: 24px;\"><strong style=\"display: block; color: #264F40; font-size: 16px; margin-bottom: 8px;\">Glycerin</strong><p style=\"margin: 0; color: #56635D; line-height: 1.8;\">Thành phần hút ẩm giúp thu hút và giữ nước trên bề mặt da, hỗ trợ duy trì độ ẩm và hạn chế cảm giác khô căng sau khi làm sạch.</p></div><div style=\"margin-bottom: 24px;\"><strong style=\"display: block; color: #264F40; font-size: 16px; margin-bottom: 8px;\">Cocamidopropyl Betaine</strong><p style=\"margin: 0; color: #56635D; line-height: 1.8;\">Thành phần làm sạch có khả năng tạo bọt, hỗ trợ loại bỏ bụi bẩn và dầu thừa với trải nghiệm làm sạch tương đối dịu nhẹ khi được phối hợp phù hợp trong công thức.</p></div><div style=\"padding: 20px; background: #F8F9F5; border-left: 3px solid #658354; border-radius: 6px; margin-top: 30px;\"><strong style=\"display: block; color: #243A30; margin-bottom: 8px;\">Bảng thành phần đầy đủ (INCI)</strong><span style=\"color: #56635D; font-size: 13px; line-height: 1.8; font-style: italic;\">Aqua, Glycerin, Cocamidopropyl Betaine, Sodium Cocoyl Glutamate, Coco-Glucoside, Curcuma Longa Root Extract, Salicylic Acid, Panthenol, Allantoin, Citric Acid, Sodium Chloride, Phenoxyethanol, Ethylhexylglycerin.</span></div>','<div style=\"margin-bottom: 24px;\"><div style=\"display: flex; gap: 15px; margin-bottom: 20px;\"><div style=\"flex-shrink: 0; width: 28px; height: 28px; background: #264F40; color: white; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 600; font-size: 14px;\">1</div><div><strong style=\"display: block; color: #264F40; font-size: 15px; margin-bottom: 4px;\">Làm ướt da</strong><p style=\"margin: 0; color: #56635D; line-height: 1.8; font-size: 14px;\">Làm ướt mặt bằng nước sạch, ưu tiên nước có nhiệt độ vừa phải.</p></div></div><div style=\"display: flex; gap: 15px; margin-bottom: 20px;\"><div style=\"flex-shrink: 0; width: 28px; height: 28px; background: #264F40; color: white; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 600; font-size: 14px;\">2</div><div><strong style=\"display: block; color: #264F40; font-size: 15px; margin-bottom: 4px;\">Lấy sản phẩm</strong><p style=\"margin: 0; color: #56635D; line-height: 1.8; font-size: 14px;\">Lấy một lượng sữa rửa mặt vừa đủ ra lòng bàn tay, thêm nước và tạo bọt nhẹ.</p></div></div><div style=\"display: flex; gap: 15px; margin-bottom: 20px;\"><div style=\"flex-shrink: 0; width: 28px; height: 28px; background: #264F40; color: white; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 600; font-size: 14px;\">3</div><div><strong style=\"display: block; color: #264F40; font-size: 15px; margin-bottom: 4px;\">Massage nhẹ nhàng</strong><p style=\"margin: 0; color: #56635D; line-height: 1.8; font-size: 14px;\">Thoa bọt lên mặt, massage theo chuyển động tròn trong khoảng 30–60 giây, tập trung vào vùng da dễ đổ dầu. Tránh chà xát mạnh và vùng mắt.</p></div></div><div style=\"display: flex; gap: 15px; margin-bottom: 30px;\"><div style=\"flex-shrink: 0; width: 28px; height: 28px; background: #264F40; color: white; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 600; font-size: 14px;\">4</div><div><strong style=\"display: block; color: #264F40; font-size: 15px; margin-bottom: 4px;\">Rửa sạch và dưỡng da</strong><p style=\"margin: 0; color: #56635D; line-height: 1.8; font-size: 14px;\">Rửa kỹ với nước, thấm khô bằng khăn mềm rồi tiếp tục với toner, tinh chất và kem dưỡng phù hợp.</p></div></div><div style=\"padding: 20px; background: #F8F9F5; border-left: 3px solid #658354; border-radius: 6px;\"><p style=\"margin: 0 0 10px 0; color: #243A30; font-size: 14px;\"><strong>Tần suất:</strong> <span style=\"color: #56635D;\">Sử dụng vào buổi sáng và tối, điều chỉnh theo nhu cầu của làn da.</span></p><p style=\"margin: 0; color: #243A30; font-size: 14px;\"><strong>Lưu ý:</strong> <span style=\"color: #56635D;\">Tránh tiếp xúc trực tiếp với mắt. Nếu công thức có Salicylic Acid, nên theo dõi phản ứng của da khi sử dụng và tránh kết hợp quá nhiều sản phẩm tẩy tế bào chết trong cùng chu trình. Ngừng sử dụng nếu xuất hiện dấu hiệu kích ứng.</span></p></div></div>','Da dầu, da hỗn hợp','150ml','turmeric-cleanser.png','[\"turmeric-cleanser.png\", \"turmeric-cleanser-1.png\"]',100,'active',0),(4,'tt-rau-ma','TT-RM-500','Nước Tẩy Trang Rau Má','Tẩy trang',249000.00,NULL,'<div style=\"margin-bottom: 24px;\"><strong style=\"display: block; color: #264F40; font-size: 18px; margin-bottom: 20px;\">Làm sạch dịu nhẹ, trở về với sự cân bằng tự nhiên</strong><p style=\"margin: 0 0 16px 0; color: #56635D; line-height: 1.8;\">Mỗi ngày, làn da phải tiếp xúc với bụi bẩn, bã nhờn và các tác nhân từ môi trường. Một bước làm sạch phù hợp giúp loại bỏ những tạp chất tích tụ, tạo tiền đề cho quy trình chăm sóc da hiệu quả hơn.</p><p style=\"margin: 0 0 16px 0; color: #56635D; line-height: 1.8;\">Nước tẩy trang rau má Mộc Yên ứng dụng công nghệ làm sạch Micellar kết hợp cảm hứng từ <b>rau má</b> – thành phần thực vật quen thuộc trong chăm sóc da. Công thức hướng đến khả năng làm sạch nhẹ nhàng, đồng thời mang lại cảm giác ẩm dịu, dễ chịu cho làn da.</p><p style=\"margin: 0 0 16px 0; color: #56635D; line-height: 1.8;\">Với dung tích 500 ml tiện dụng, sản phẩm phù hợp cho quy trình chăm sóc da hằng ngày, giúp việc làm sạch trở thành một bước chăm sóc đơn giản và thư thái.</p><div style=\"margin-top: 24px; padding: 16px 20px; background: #F8F9F5; border-left: 3px solid #658354; border-radius: 6px;\"><p style=\"margin: 0; color: #56635D; line-height: 1.8; font-style: italic; font-size: 14px;\"><b>Thông điệp:</b> Làm sạch tinh giản. Dịu lành mỗi ngày.</p></div></div>','Nước tẩy trang Rau Má Mộc Yên ứng dụng công nghệ Micellar giúp làm sạch sâu bụi bẩn và lớp trang điểm mà không gây khô căng. Chiết xuất rau má và Panthenol mang lại cảm giác dịu mát, hỗ trợ bảo vệ hàng rào da trong chu trình chăm sóc hằng ngày.','<div style=\"margin-bottom: 24px;\"><ul style=\"list-style: none; padding: 0; margin: 0;\"><li style=\"display: flex; gap: 12px; margin-bottom: 18px; color: #56635D; line-height: 1.8;\"><span style=\"color: #658354; font-size: 18px;\">✦</span><div><strong style=\"color: #264F40;\">Làm sạch hiệu quả:</strong> Hỗ trợ loại bỏ bụi bẩn, bã nhờn và lớp trang điểm thông thường trên da.</div></li><li style=\"display: flex; gap: 12px; margin-bottom: 18px; color: #56635D; line-height: 1.8;\"><span style=\"color: #658354; font-size: 18px;\">✦</span><div><strong style=\"color: #264F40;\">Làm dịu da:</strong> Chiết xuất rau má góp phần mang lại cảm giác dễ chịu cho làn da.</div></li><li style=\"display: flex; gap: 12px; margin-bottom: 18px; color: #56635D; line-height: 1.8;\"><span style=\"color: #658354; font-size: 18px;\">✦</span><div><strong style=\"color: #264F40;\">Duy trì độ ẩm:</strong> Panthenol hỗ trợ giữ ẩm, hạn chế cảm giác khô căng sau khi làm sạch.</div></li><li style=\"display: flex; gap: 12px; margin-bottom: 18px; color: #56635D; line-height: 1.8;\"><span style=\"color: #658354; font-size: 18px;\">✦</span><div><strong style=\"color: #264F40;\">Hỗ trợ bảo vệ hàng rào da:</strong> Hướng đến làn da mềm mại, cân bằng sau bước tẩy trang.</div></li></ul></div>','<div style=\"margin-bottom: 24px;\"><strong style=\"display: block; color: #264F40; font-size: 16px; margin-bottom: 8px;\">Chiết xuất rau má (Centella Asiatica Extract)</strong><p style=\"margin: 0; color: #56635D; line-height: 1.8;\">Thành phần thực vật thường được sử dụng trong mỹ phẩm chăm sóc da nhờ đặc tính làm dịu. Góp phần tạo nên định hướng chăm sóc da dịu nhẹ của Mộc Yên.</p></div><div style=\"margin-bottom: 24px;\"><strong style=\"display: block; color: #264F40; font-size: 16px; margin-bottom: 8px;\">Panthenol (Pro-vitamin B5)</strong><p style=\"margin: 0; color: #56635D; line-height: 1.8;\">Thành phần hỗ trợ dưỡng ẩm và duy trì cảm giác mềm mại, dễ chịu cho làn da sau khi làm sạch.</p></div><div style=\"margin-bottom: 24px;\"><strong style=\"display: block; color: #264F40; font-size: 16px; margin-bottom: 8px;\">Hệ làm sạch Micellar</strong><p style=\"margin: 0; color: #56635D; line-height: 1.8;\">Các phân tử làm sạch giúp thu hút và cuốn đi bụi bẩn, bã nhờn cùng lớp trang điểm, hỗ trợ làm sạch da mà không cần chà xát mạnh.</p></div><div style=\"padding: 20px; background: #F8F9F5; border-left: 3px solid #658354; border-radius: 6px; margin-top: 30px;\"><strong style=\"display: block; color: #243A30; margin-bottom: 8px;\">Bảng thành phần đầy đủ (INCI)</strong><span style=\"color: #56635D; font-size: 13px; line-height: 1.8; font-style: italic;\">Aqua, PEG-6 Caprylic/Capric Glycerides, Glycerin, Centella Asiatica Extract, Panthenol, Allantoin, Disodium EDTA, Sodium Benzoate, Potassium Sorbate, Citric Acid.</span></div>','<div style=\"margin-bottom: 24px;\"><div style=\"display: flex; gap: 15px; margin-bottom: 20px;\"><div style=\"flex-shrink: 0; width: 28px; height: 28px; background: #264F40; color: white; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 600; font-size: 14px;\">1</div><div><strong style=\"display: block; color: #264F40; font-size: 15px; margin-bottom: 4px;\">Thấm sản phẩm</strong><p style=\"margin: 0; color: #56635D; line-height: 1.8; font-size: 14px;\">Cho một lượng nước tẩy trang vừa đủ lên bông tẩy trang sạch.</p></div></div><div style=\"display: flex; gap: 15px; margin-bottom: 20px;\"><div style=\"flex-shrink: 0; width: 28px; height: 28px; background: #264F40; color: white; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 600; font-size: 14px;\">2</div><div><strong style=\"display: block; color: #264F40; font-size: 15px; margin-bottom: 4px;\">Làm sạch da</strong><p style=\"margin: 0; color: #56635D; line-height: 1.8; font-size: 14px;\">Nhẹ nhàng lau khắp mặt theo chiều từ trong ra ngoài. Với vùng trang điểm đậm, áp bông lên da vài giây trước khi lau nhẹ.</p></div></div><div style=\"display: flex; gap: 15px; margin-bottom: 30px;\"><div style=\"flex-shrink: 0; width: 28px; height: 28px; background: #264F40; color: white; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 600; font-size: 14px;\">3</div><div><strong style=\"display: block; color: #264F40; font-size: 15px; margin-bottom: 4px;\">Tiếp tục quy trình chăm sóc da</strong><p style=\"margin: 0; color: #56635D; line-height: 1.8; font-size: 14px;\">Sau khi tẩy trang, sử dụng sữa rửa mặt phù hợp, sau đó tiếp tục các bước dưỡng da.</p></div></div><div style=\"padding: 20px; background: #F8F9F5; border-left: 3px solid #658354; border-radius: 6px;\"><p style=\"margin: 0 0 10px 0; color: #243A30; font-size: 14px;\"><strong>Tần suất:</strong> <span style=\"color: #56635D;\">Sử dụng hằng ngày vào buổi sáng hoặc buổi tối khi cần làm sạch da.</span></p><p style=\"margin: 0; color: #243A30; font-size: 14px;\"><strong>Lưu ý:</strong> <span style=\"color: #56635D;\">Tránh tiếp xúc trực tiếp với mắt. Không chà xát mạnh lên da. Nếu xuất hiện dấu hiệu kích ứng, ngừng sử dụng.</span></p></div></div>','Mọi loại da','500ml','centella-micellar-water.png','[\"centella-micellar-water.png\", \"centella-micellar-water-1.png\"]',100,'active',0),(5,'tt-rau-ma','TT-RM-1L','Nước Tẩy Trang Rau Má','Tẩy trang',399000.00,NULL,'<div style=\"margin-bottom: 24px;\"><strong style=\"display: block; color: #264F40; font-size: 18px; margin-bottom: 20px;\">Làm sạch dịu nhẹ, trở về với sự cân bằng tự nhiên</strong><p style=\"margin: 0 0 16px 0; color: #56635D; line-height: 1.8;\">Mỗi ngày, làn da phải tiếp xúc với bụi bẩn, bã nhờn và các tác nhân từ môi trường. Một bước làm sạch phù hợp giúp loại bỏ những tạp chất tích tụ, tạo tiền đề cho quy trình chăm sóc da hiệu quả hơn.</p><p style=\"margin: 0 0 16px 0; color: #56635D; line-height: 1.8;\">Nước tẩy trang rau má Mộc Yên ứng dụng công nghệ làm sạch Micellar kết hợp cảm hứng từ <b>rau má</b> – thành phần thực vật quen thuộc trong chăm sóc da. Công thức hướng đến khả năng làm sạch nhẹ nhàng, đồng thời mang lại cảm giác ẩm dịu, dễ chịu cho làn da.</p><p style=\"margin: 0 0 16px 0; color: #56635D; line-height: 1.8;\">Với dung tích 500 ml tiện dụng, sản phẩm phù hợp cho quy trình chăm sóc da hằng ngày, giúp việc làm sạch trở thành một bước chăm sóc đơn giản và thư thái.</p><div style=\"margin-top: 24px; padding: 16px 20px; background: #F8F9F5; border-left: 3px solid #658354; border-radius: 6px;\"><p style=\"margin: 0; color: #56635D; line-height: 1.8; font-style: italic; font-size: 14px;\"><b>Thông điệp:</b> Làm sạch tinh giản. Dịu lành mỗi ngày.</p></div></div>','Nước tẩy trang Rau Má Mộc Yên ứng dụng công nghệ Micellar giúp làm sạch sâu bụi bẩn và lớp trang điểm mà không gây khô căng. Chiết xuất rau má và Panthenol mang lại cảm giác dịu mát, hỗ trợ bảo vệ hàng rào da trong chu trình chăm sóc hằng ngày.','<div style=\"margin-bottom: 24px;\"><ul style=\"list-style: none; padding: 0; margin: 0;\"><li style=\"display: flex; gap: 12px; margin-bottom: 18px; color: #56635D; line-height: 1.8;\"><span style=\"color: #658354; font-size: 18px;\">✦</span><div><strong style=\"color: #264F40;\">Làm sạch hiệu quả:</strong> Hỗ trợ loại bỏ bụi bẩn, bã nhờn và lớp trang điểm thông thường trên da.</div></li><li style=\"display: flex; gap: 12px; margin-bottom: 18px; color: #56635D; line-height: 1.8;\"><span style=\"color: #658354; font-size: 18px;\">✦</span><div><strong style=\"color: #264F40;\">Làm dịu da:</strong> Chiết xuất rau má góp phần mang lại cảm giác dễ chịu cho làn da.</div></li><li style=\"display: flex; gap: 12px; margin-bottom: 18px; color: #56635D; line-height: 1.8;\"><span style=\"color: #658354; font-size: 18px;\">✦</span><div><strong style=\"color: #264F40;\">Duy trì độ ẩm:</strong> Panthenol hỗ trợ giữ ẩm, hạn chế cảm giác khô căng sau khi làm sạch.</div></li><li style=\"display: flex; gap: 12px; margin-bottom: 18px; color: #56635D; line-height: 1.8;\"><span style=\"color: #658354; font-size: 18px;\">✦</span><div><strong style=\"color: #264F40;\">Hỗ trợ bảo vệ hàng rào da:</strong> Hướng đến làn da mềm mại, cân bằng sau bước tẩy trang.</div></li></ul></div>','<div style=\"margin-bottom: 24px;\"><strong style=\"display: block; color: #264F40; font-size: 16px; margin-bottom: 8px;\">Chiết xuất rau má (Centella Asiatica Extract)</strong><p style=\"margin: 0; color: #56635D; line-height: 1.8;\">Thành phần thực vật thường được sử dụng trong mỹ phẩm chăm sóc da nhờ đặc tính làm dịu. Góp phần tạo nên định hướng chăm sóc da dịu nhẹ của Mộc Yên.</p></div><div style=\"margin-bottom: 24px;\"><strong style=\"display: block; color: #264F40; font-size: 16px; margin-bottom: 8px;\">Panthenol (Pro-vitamin B5)</strong><p style=\"margin: 0; color: #56635D; line-height: 1.8;\">Thành phần hỗ trợ dưỡng ẩm và duy trì cảm giác mềm mại, dễ chịu cho làn da sau khi làm sạch.</p></div><div style=\"margin-bottom: 24px;\"><strong style=\"display: block; color: #264F40; font-size: 16px; margin-bottom: 8px;\">Hệ làm sạch Micellar</strong><p style=\"margin: 0; color: #56635D; line-height: 1.8;\">Các phân tử làm sạch giúp thu hút và cuốn đi bụi bẩn, bã nhờn cùng lớp trang điểm, hỗ trợ làm sạch da mà không cần chà xát mạnh.</p></div><div style=\"padding: 20px; background: #F8F9F5; border-left: 3px solid #658354; border-radius: 6px; margin-top: 30px;\"><strong style=\"display: block; color: #243A30; margin-bottom: 8px;\">Bảng thành phần đầy đủ (INCI)</strong><span style=\"color: #56635D; font-size: 13px; line-height: 1.8; font-style: italic;\">Aqua, PEG-6 Caprylic/Capric Glycerides, Glycerin, Centella Asiatica Extract, Panthenol, Allantoin, Disodium EDTA, Sodium Benzoate, Potassium Sorbate, Citric Acid.</span></div>','<div style=\"margin-bottom: 24px;\"><div style=\"display: flex; gap: 15px; margin-bottom: 20px;\"><div style=\"flex-shrink: 0; width: 28px; height: 28px; background: #264F40; color: white; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 600; font-size: 14px;\">1</div><div><strong style=\"display: block; color: #264F40; font-size: 15px; margin-bottom: 4px;\">Thấm sản phẩm</strong><p style=\"margin: 0; color: #56635D; line-height: 1.8; font-size: 14px;\">Cho một lượng nước tẩy trang vừa đủ lên bông tẩy trang sạch.</p></div></div><div style=\"display: flex; gap: 15px; margin-bottom: 20px;\"><div style=\"flex-shrink: 0; width: 28px; height: 28px; background: #264F40; color: white; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 600; font-size: 14px;\">2</div><div><strong style=\"display: block; color: #264F40; font-size: 15px; margin-bottom: 4px;\">Làm sạch da</strong><p style=\"margin: 0; color: #56635D; line-height: 1.8; font-size: 14px;\">Nhẹ nhàng lau khắp mặt theo chiều từ trong ra ngoài. Với vùng trang điểm đậm, áp bông lên da vài giây trước khi lau nhẹ.</p></div></div><div style=\"display: flex; gap: 15px; margin-bottom: 30px;\"><div style=\"flex-shrink: 0; width: 28px; height: 28px; background: #264F40; color: white; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 600; font-size: 14px;\">3</div><div><strong style=\"display: block; color: #264F40; font-size: 15px; margin-bottom: 4px;\">Tiếp tục quy trình chăm sóc da</strong><p style=\"margin: 0; color: #56635D; line-height: 1.8; font-size: 14px;\">Sau khi tẩy trang, sử dụng sữa rửa mặt phù hợp, sau đó tiếp tục các bước dưỡng da.</p></div></div><div style=\"padding: 20px; background: #F8F9F5; border-left: 3px solid #658354; border-radius: 6px;\"><p style=\"margin: 0 0 10px 0; color: #243A30; font-size: 14px;\"><strong>Tần suất:</strong> <span style=\"color: #56635D;\">Sử dụng hằng ngày vào buổi sáng hoặc buổi tối khi cần làm sạch da.</span></p><p style=\"margin: 0; color: #243A30; font-size: 14px;\"><strong>Lưu ý:</strong> <span style=\"color: #56635D;\">Tránh tiếp xúc trực tiếp với mắt. Không chà xát mạnh lên da. Nếu xuất hiện dấu hiệu kích ứng, ngừng sử dụng.</span></p></div></div>','Mọi loại da','1L','centella-micellar-water.png','[\"centella-micellar-water.png\", \"centella-micellar-water-2.png\"]',100,'active',0),(6,'tt-hoa-hong','TT-HH-500','Nước Tẩy Trang Hoa Hồng','Tẩy trang',269000.00,NULL,'<div style=\"margin-bottom: 24px;\"><strong style=\"display: block; color: #264F40; font-size: 18px; margin-bottom: 20px;\">Làm sạch nhẹ nhàng, lưu giữ nét mềm mại của làn da</strong><p style=\"margin: 0 0 16px 0; color: #56635D; line-height: 1.8;\">Sau một ngày tiếp xúc với bụi bẩn, bã nhờn và các sản phẩm trang điểm, làn da cần được làm sạch để duy trì trạng thái thông thoáng và dễ chịu. Nước tẩy trang Hoa Hồng Mộc Yên ứng dụng công nghệ làm sạch Micellar, giúp cuốn đi tạp chất trên bề mặt da mà không cần chà xát mạnh.</p><p style=\"margin: 0 0 16px 0; color: #56635D; line-height: 1.8;\">Lấy cảm hứng từ <b>vẻ đẹp dịu dàng của hoa hồng</b>, sản phẩm kết hợp thành phần làm sạch với Glycerin dưỡng ẩm, hỗ trợ hạn chế cảm giác khô căng sau khi tẩy trang. Kết cấu lỏng nhẹ, dễ sử dụng giúp sản phẩm phù hợp với chu trình chăm sóc da hằng ngày.</p><p style=\"margin: 0 0 16px 0; color: #56635D; line-height: 1.8;\">Với sắc hồng đặc trưng cùng tinh thần gần gũi thiên nhiên của Mộc Yên, Rose Micellar Water mang đến một bước làm sạch đơn giản, nhẹ nhàng, giúp làn da sẵn sàng cho các bước dưỡng tiếp theo.</p><div style=\"margin-top: 24px; padding: 16px 20px; background: #F8F9F5; border-left: 3px solid #658354; border-radius: 6px;\"><p style=\"margin: 0; color: #56635D; line-height: 1.8; font-style: italic; font-size: 14px;\"><b>Thông điệp:</b> Dịu dàng làm sạch, nâng niu làn da.</p></div></div>','Nước tẩy trang Hoa Hồng Mộc Yên với công nghệ Micellar giúp làm sạch sâu lớp trang điểm và bã nhờn mà không gây khô ráp. Chiết xuất hoa hồng cùng Glycerin mang lại cảm giác da mềm mại, ẩm mượt và thư giãn sau khi sử dụng.','<div style=\"margin-bottom: 24px;\"><ul style=\"list-style: none; padding: 0; margin: 0;\"><li style=\"display: flex; gap: 12px; margin-bottom: 18px; color: #56635D; line-height: 1.8;\"><span style=\"color: #658354; font-size: 18px;\">✦</span><div><strong style=\"color: #264F40;\">Loại bỏ bụi bẩn:</strong> Hỗ trợ cuốn đi bụi bẩn, tạp chất và dầu thừa trên bề mặt da.</div></li><li style=\"display: flex; gap: 12px; margin-bottom: 18px; color: #56635D; line-height: 1.8;\"><span style=\"color: #658354; font-size: 18px;\">✦</span><div><strong style=\"color: #264F40;\">Làm sạch lớp trang điểm nhẹ:</strong> Giúp loại bỏ lớp trang điểm thông thường và kem chống nắng không chống nước.</div></li><li style=\"display: flex; gap: 12px; margin-bottom: 18px; color: #56635D; line-height: 1.8;\"><span style=\"color: #658354; font-size: 18px;\">✦</span><div><strong style=\"color: #264F40;\">Duy trì độ ẩm:</strong> Glycerin hỗ trợ giữ ẩm, hạn chế cảm giác khô căng sau khi làm sạch.</div></li><li style=\"display: flex; gap: 12px; margin-bottom: 18px; color: #56635D; line-height: 1.8;\"><span style=\"color: #658354; font-size: 18px;\">✦</span><div><strong style=\"color: #264F40;\">Mang lại cảm giác dễ chịu:</strong> Hỗ trợ duy trì bề mặt da mềm mại, tươi mát sau khi tẩy trang.</div></li><li style=\"display: flex; gap: 12px; margin-bottom: 18px; color: #56635D; line-height: 1.8;\"><span style=\"color: #658354; font-size: 18px;\">✦</span><div><strong style=\"color: #264F40;\">Hỗ trợ chu trình chăm sóc da:</strong> Giúp loại bỏ tạp chất trước bước rửa mặt và các bước dưỡng da tiếp theo.</div></li></ul></div>','<div style=\"margin-bottom: 24px;\"><strong style=\"display: block; color: #264F40; font-size: 16px; margin-bottom: 8px;\">Chiết xuất hoa hồng (Rosa Damascena Flower Extract)</strong><p style=\"margin: 0; color: #56635D; line-height: 1.8;\">Thành phần có nguồn gốc thực vật, được sử dụng trong mỹ phẩm nhằm hỗ trợ chăm sóc và làm dịu da. Chiết xuất hoa hồng tạo nên cảm hứng chủ đạo cho sản phẩm, mang đến hình ảnh thanh lịch và dịu dàng đặc trưng của dòng chăm sóc da Mộc Yên.</p></div><div style=\"margin-bottom: 24px;\"><strong style=\"display: block; color: #264F40; font-size: 16px; margin-bottom: 8px;\">Glycerin</strong><p style=\"margin: 0; color: #56635D; line-height: 1.8;\">Thành phần hút ẩm giúp thu hút và giữ nước trên bề mặt da, hỗ trợ duy trì độ ẩm và hạn chế cảm giác khô căng sau khi tẩy trang.</p></div><div style=\"margin-bottom: 24px;\"><strong style=\"display: block; color: #264F40; font-size: 16px; margin-bottom: 8px;\">Poloxamer 184</strong><p style=\"margin: 0; color: #56635D; line-height: 1.8;\">Thành phần hỗ trợ làm sạch thường được sử dụng trong các công thức nước tẩy trang Micellar, giúp cuốn đi bụi bẩn và tạp chất trên bề mặt da.</p></div><div style=\"margin-bottom: 24px;\"><strong style=\"display: block; color: #264F40; font-size: 16px; margin-bottom: 8px;\">Panthenol (Vitamin B5)</strong><p style=\"margin: 0; color: #56635D; line-height: 1.8;\">Hỗ trợ dưỡng ẩm và làm dịu da, góp phần duy trì cảm giác mềm mại sau bước làm sạch.</p></div><div style=\"padding: 20px; background: #F8F9F5; border-left: 3px solid #658354; border-radius: 6px; margin-top: 30px;\"><strong style=\"display: block; color: #243A30; margin-bottom: 8px;\">Bảng thành phần đầy đủ (INCI)</strong><span style=\"color: #56635D; font-size: 13px; line-height: 1.8; font-style: italic;\">Aqua, Glycerin, Poloxamer 184, Rosa Damascena Flower Extract, Panthenol, Disodium EDTA, Citric Acid, Phenoxyethanol, Ethylhexylglycerin.</span></div>','<div style=\"margin-bottom: 24px;\"><div style=\"display: flex; gap: 15px; margin-bottom: 20px;\"><div style=\"flex-shrink: 0; width: 28px; height: 28px; background: #264F40; color: white; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 600; font-size: 14px;\">1</div><div><strong style=\"display: block; color: #264F40; font-size: 15px; margin-bottom: 4px;\">Thấm nước tẩy trang</strong><p style=\"margin: 0; color: #56635D; line-height: 1.8; font-size: 14px;\">Lấy một lượng nước tẩy trang vừa đủ ra bông tẩy trang sạch.</p></div></div><div style=\"display: flex; gap: 15px; margin-bottom: 20px;\"><div style=\"flex-shrink: 0; width: 28px; height: 28px; background: #264F40; color: white; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 600; font-size: 14px;\">2</div><div><strong style=\"display: block; color: #264F40; font-size: 15px; margin-bottom: 4px;\">Lau nhẹ nhàng</strong><p style=\"margin: 0; color: #56635D; line-height: 1.8; font-size: 14px;\">Nhẹ nhàng lau khắp mặt theo chiều từ trong ra ngoài, tránh chà xát mạnh. Với vùng trang điểm đậm, áp bông lên da vài giây trước khi lau.</p></div></div><div style=\"display: flex; gap: 15px; margin-bottom: 20px;\"><div style=\"flex-shrink: 0; width: 28px; height: 28px; background: #264F40; color: white; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 600; font-size: 14px;\">3</div><div><strong style=\"display: block; color: #264F40; font-size: 15px; margin-bottom: 4px;\">Làm sạch vùng mắt và môi</strong><p style=\"margin: 0; color: #56635D; line-height: 1.8; font-size: 14px;\">Sử dụng bông riêng cho vùng mắt và môi. Tránh để sản phẩm tiếp xúc trực tiếp với mắt.</p></div></div><div style=\"display: flex; gap: 15px; margin-bottom: 30px;\"><div style=\"flex-shrink: 0; width: 28px; height: 28px; background: #264F40; color: white; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 600; font-size: 14px;\">4</div><div><strong style=\"display: block; color: #264F40; font-size: 15px; margin-bottom: 4px;\">Rửa mặt</strong><p style=\"margin: 0; color: #56635D; line-height: 1.8; font-size: 14px;\">Tiếp tục sử dụng sữa rửa mặt phù hợp để hoàn thiện bước làm sạch kép, sau đó thực hiện các bước dưỡng da.</p></div></div><div style=\"padding: 20px; background: #F8F9F5; border-left: 3px solid #658354; border-radius: 6px;\"><p style=\"margin: 0 0 10px 0; color: #243A30; font-size: 14px;\"><strong>Tần suất:</strong> <span style=\"color: #56635D;\">Sử dụng vào buổi tối hằng ngày hoặc khi cần loại bỏ kem chống nắng và lớp trang điểm.</span></p><p style=\"margin: 0; color: #243A30; font-size: 14px;\"><strong>Lưu ý:</strong> <span style=\"color: #56635D;\">Không chà xát mạnh trên da. Với lớp trang điểm chống nước, có thể cần sản phẩm tẩy trang chuyên dụng. Ngừng sử dụng nếu xuất hiện dấu hiệu kích ứng.</span></p></div></div>','Da nhạy cảm','500ml','rose-micellar-water.png','[\"rose-micellar-water.png\", \"rose-micellar-water-1.png\"]',100,'active',1),(7,'tt-hoa-hong','TT-HH-1L','Nước Tẩy Trang Hoa Hồng','Tẩy trang',419000.00,NULL,'<div style=\"margin-bottom: 24px;\"><strong style=\"display: block; color: #264F40; font-size: 18px; margin-bottom: 20px;\">Làm sạch nhẹ nhàng